'use server'

import { updateTag } from 'next/cache'
import { createPostRecord } from './lib/posts'

export async function createPost(formData: FormData) {
  const title = formData.get('title')
  const content = formData.get('content')

  if (typeof title !== 'string' || !title.trim()) {
    throw new Error('A post title is required.')
  }

  if (typeof content !== 'string' || !content.trim()) {
    throw new Error('Post content is required.')
  }

  await createPostRecord({
    title: title.trim(),
    content: content.trim(),
  })

  // Expire the tagged list immediately so the next read waits for fresh data.
  updateTag('posts')
}
import { randomUUID } from 'node:crypto'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { unstable_cache } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

type NewPost = Pick<Post, 'title' | 'content'>

const postsFile = join(process.cwd(), 'data', 'posts.json')

async function readPostRecords(): Promise<Post[]> {
  try {
    const contents = await readFile(postsFile, 'utf8')
    return JSON.parse(contents) as Post[]
  } catch (error) {
    if (isMissingFile(error)) {
      return []
    }

    throw error
  }
}

function isMissingFile(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    error.code === 'ENOENT'
  )
}

export async function createPostRecord(input: NewPost): Promise<Post> {
  const posts = await readPostRecords()
  const post: Post = {
    id: randomUUID(),
    title: input.title,
    content: input.content,
    createdAt: new Date().toISOString(),
  }

  await mkdir(dirname(postsFile), { recursive: true })
  await writeFile(postsFile, JSON.stringify([post, ...posts], null, 2))

  return post
}

const getCachedPosts = unstable_cache(
  async () => readPostRecords(),
  ['posts'],
  { tags: ['posts'] },
)

export function getPosts(): Promise<Post[]> {
  return getCachedPosts()
}
